theorem backward_forward_id_add (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (dim + dim), backwardAdd dim s (forwardAdd dim s v) = v :=
  fun v =>
    let sp := Vec.split dim dim v
    let h1 := halves_inverse s h sp.fst sp.snd
    Eq.trans
      (Eq.refl (backwardAdd dim s (forwardAdd dim s v)))
      (Eq.trans
        (Eq.refl (Vec.append (backwardHalves s (forwardHalves s sp.fst sp.snd)).fst (backwardHalves s (forwardHalves s sp.fst sp.snd)).snd))
        (Eq.trans
          (congrArg (fun (p : Vec α dim × Vec α dim) => Vec.append p.fst p.snd) h1)
          (Vec.append_split dim dim v)))

theorem forward_backward_id_add (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (dim + dim), forwardAdd dim s (backwardAdd dim s v) = v :=
  fun v =>
    let sp := Vec.split dim dim v
    let h1 := halves_inverse s h sp.fst sp.snd
    let h2 :
      forwardHalves s (backwardHalves s sp.fst sp.snd) = (sp.fst, sp.snd) :=
      match h1 with
      | Eq.refl _ => Eq.refl (forwardHalves s (backwardHalves s sp.fst sp.snd))
    Eq.trans
      (Eq.refl (forwardAdd dim s (backwardAdd dim s v)))
      (Eq.trans
        (Eq.refl (Vec.append (forwardHalves s (backwardHalves s sp.fst sp.snd)).fst (forwardHalves s (backwardHalves s sp.fst sp.snd)).snd))
        (Eq.trans
          (congrArg (fun (p : Vec α dim × Vec α dim) => Vec.append p.fst p.snd) h2)
          (Vec.append_split dim dim v)))

theorem backward_forward_id (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), backwardCore dim s (forwardCore dim s v) = v :=
  fun v =>
    let v' := Vec.cast (two_mul_nat dim) v
    let t := backward_forward_id_add dim s h v'
    Eq.trans
      (Eq.refl (backwardCore dim s (forwardCore dim s v)))
      (Eq.trans
        (Eq.refl (Vec.cast (Eq.symm (two_mul_nat dim)) (forwardAdd dim s (Vec.cast (two_mul_nat dim) v))))
        (Eq.trans
          (congrArg (fun t' => Vec.cast (Eq.symm (two_mul_nat dim)) t') (backward_forward_id_add dim s h (Vec.cast (two_mul_nat dim) v)))
          (Eq.refl v)))

theorem forward_backward_id (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), forwardCore dim s (backwardCore dim s v) = v :=
  fun v =>
    let v' := Vec.cast (two_mul_nat dim) v
    let t := forward_backward_id_add dim s h v'
    Eq.trans
      (Eq.refl (forwardCore dim s (backwardCore dim s v)))
      (Eq.trans
        (Eq.refl (Vec.cast (Eq.symm (two_mul_nat dim)) (forwardAdd dim s (Vec.cast (two_mul_nat dim) v))))
        (Eq.trans
          (congrArg (fun t' => Vec.cast (Eq.symm (two_mul_nat dim)) t') (forward_backward_id_add dim s h (Vec.cast (two_mul_nat dim) v)))
          (Eq.refl v)))

def mixForwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  forwardCore dim s v

def mixBackwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  backwardCore dim s v

theorem mix_round_trip (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), mixBackwardCore dim s (mixForwardCore dim s v) = v :=
  fun v => backward_forward_id dim s h v

end RingSection


