RÉTEG 2 — TENSOR MODELL


Definiáld:

  inductive InitResult (α : Type u) where
  | ok : (shape : List Nat) → (data : List α) →
         ValidShapeB shape →
         data.length = shapeProd shape →
         (∀ x, x ∈ data → x = Zero.zero) →
         InitResult α
  | invalidShape : InitResult α
  | overflow : InitResult α
  | allocFail : InitResult α

  def tensorInit (α : Type u) [Zero α] (shape : List Nat) : InitResult α :=
    match shape with
    | [] => InitResult.invalidShape
    | xs =>
      if h1 : ShapeAllPositive xs then
        if h2 : ShapeProdBounded xs then
          let d := List.replicate (shapeProd xs) (Zero.zero (α := α))
          InitResult.ok xs d ⟨List.nonempty_of_ne_nil xs (by cases xs <;> simp), h1, h2⟩
            (List.length_replicate _ _)
            (fun x hx => List.mem_replicate.mp hx |>.2)
        else InitResult.overflow
      else InitResult.invalidShape

