            ((s * s) * x2 + 0) + - ((s * s) * (-x2)) :=
            congrArg (fun t => ((s * s) * x2 + t) + - ((s * s) * (-x2))) t11
          let t13 :
            ((s * s) * x2 + 0) + - ((s * s) * (-x2)) =
            (s * s) * x2 + - ((s * s) * (-x2)) :=
            Eq.symm (add_assoc ((s * s) * x2) 0 (- ((s * s) * (-x2))))
          let t14 :
            - ((s * s) * (-x2)) = (s * s) * x2 :=
